{
  "implementation": "def solve(case):
    initial_state = case["initial_state"]
    max_steps = case["max_steps"]
    tool_observations = case["tool_observations"]
    transitions = case["transitions"]

    state = initial_state
    trace = []
    step = 0
    final = None
    status = None

    while step < max_steps:
        state_def = transitions.get(state)
        if state_def is None:
            break
        if state_def["kind"] == "final":
            final = state_def["value"]
            status = "success"
            break
        elif state_def["kind"] == "action":
            action = state_def["action"]
            observation = tool_observations.get(action, "")
            if observation in state_def["next_by_observation"]:
                next_state = state_def["next_by_observation"][observation]
            else:
                next_state = state_def["default_next"]
            step += 1
            trace.append({
                "step": step,
                "action": action,
                "observation": observation,
                "state": next_state
            })
            state = next_state
            next_def = transitions.get(state)
            if next_def and next_def["kind"] == "final":
                final = next_def["value"]
                status = "success"
                break
        else:
            break
    else:
        if status is None:
            status = "max_steps_reached"
            final = None

    if status is None:
        state_def = transitions.get(initial_state)
        if state_def and state_def["kind"] == "final":
            final = state_def["value"]
            status = "success"
        else:
            status = "max_steps_reached"
            final = None

    return {
        "final": final,
        "status": status,
        "trace": trace
    }"
}
